const JSZip = require('jszip');

// Get file from previous node
const items = $input.all();
const fileData = items[0].binary?.data;
const bookId = $('Webhook').item.json.book_id;

if (!fileData) {
  throw new Error('No file data received');
}

// Parse EPUB
const zip = await JSZip.loadAsync(Buffer.from(fileData.data, 'base64'));
const chunks = [];

// Find all HTML/XHTML files
const files = Object.keys(zip.files);
const htmlFiles = files.filter(f => /\.(x?html?)$/i.test(f) && !zip.files[f].dir);

let chunkIndex = 0;
let chapterNumber = 0;

for (const filePath of htmlFiles) {
  const content = await zip.files[filePath].async('string');
  chapterNumber++;

  // Extract chapter title
  const titleMatch = content.match(/<title>([^<]+)<\/title>/i) || 
                     content.match(/<h1[^>]*>([^<]+)<\/h1>/i) ||
                     content.match(/<h2[^>]*>([^<]+)<\/h2>/i);
  const chapterTitle = titleMatch ? titleMatch[1].trim() : `Chapter ${chapterNumber}`;

  // Strip HTML and clean text
  let textContent = content
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, '\n')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#?\w+;/g, ' ')
    .replace(/\n+/g, '\n')
    .trim();

  // Split into paragraphs
  const paragraphs = textContent
    .split(/\n+/)
    .map(p => p.trim())
    .filter(p => p.length > 30);

  // Create chunks (~500 tokens each, roughly 2000 chars)
  let currentChunk = '';
  let paragraphIndex = 0;

  for (const para of paragraphs) {
    if (currentChunk.length + para.length > 2000 && currentChunk.length > 100) {
      chunks.push({
        book_id: bookId,
        chapter_number: chapterNumber,
        chapter_title: chapterTitle,
        chunk_index: chunkIndex++,
        content: currentChunk.trim(),
        content_type: 'body',
        paragraph_index: paragraphIndex,
        word_count: currentChunk.split(/\s+/).length
      });
      currentChunk = para;
    } else {
      currentChunk += (currentChunk ? '\n\n' : '') + para;
    }
    paragraphIndex++;
  }

  // Last chunk for this file
  if (currentChunk.length > 100) {
    chunks.push({
      book_id: bookId,
      chapter_number: chapterNumber,
      chapter_title: chapterTitle,
      chunk_index: chunkIndex++,
      content: currentChunk.trim(),
      content_type: 'body',
      paragraph_index: paragraphIndex,
      word_count: currentChunk.split(/\s+/).length
    });
  }
}

// Sample content for analysis (first ~8000 chars)
const sampleContent = chunks
  .slice(0, 5)
  .map(c => c.content)
  .join('\n\n---\n\n')
  .slice(0, 8000);

return {
  json: {
    book_id: bookId,
    chunks: chunks,
    sampleContent: sampleContent,
    totalChunks: chunks.length,
    totalChapters: chapterNumber
  }
};

// Combine chunks with embeddings
const chunks = $('Extract Text and Chunk').item.json.chunks;
const embeddings = $('Generate Embeddings').item.json;

// Note: The actual embedding format depends on how n8n returns them
// This may need adjustment based on actual output
const chunksWithEmbeddings = chunks.map((chunk, i) => ({
  ...chunk,
  embedding: embeddings[i] || null
}));

return {
  json: {
    book_id: $('Extract Text and Chunk').item.json.book_id,
    chunksWithEmbeddings: chunksWithEmbeddings,
    sampleContent: $('Extract Text and Chunk').item.json.sampleContent,
    totalChunks: chunks.length
  }
};
